//! The node's pixel effects, as the console draws them, against the node's own bytes.
//!
//! `testdata/pixel-effects.json` is generated by the OpenHaunt node firmware from its C
//! (`firmware/test/host/pixfx_corpus.c`, kept beside the spec as `docs/14-pixel-
//! effects.json`) and checked there exactly. This holds `pult_render::pixfx` to it.
//!
//! **Within one byte, and that is not a fudge.** The two sides call their platform's
//! `sinf`/`cosf` and may let the compiler fuse a multiply and an add; either can move the
//! last bit of a float, and a float that lands on a rounding edge then moves a byte by
//! one. Anything more than one is a different formula, which is what this is for — and
//! the count of off-by-ones is bounded too, so a wrong formula cannot hide in them.
//!
//! A changed effect in the firmware means a regenerated corpus there, copied here, and
//! this test saying what the console has to follow.

use pult_render::pixfx::{phase_at, render, PixelEffect, PixelParams};
use serde::Deserialize;

#[derive(Deserialize)]
struct Case {
    name: String,
    effect: String,
    color: [u8; 3],
    color2: [u8; 3],
    brightness: f32,
    speed: f32,
    size: f32,
    reverse: bool,
    mirror: bool,
    segments: i32,
    now_ms: i64,
    count: u16,
    phase: f32,
    rgb: String,
}

#[derive(Deserialize)]
struct Corpus {
    cases: Vec<Case>,
}

fn bytes(hex: &str) -> Vec<u8> {
    (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap()).collect()
}

#[test]
fn every_effect_draws_what_the_node_draws() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../testdata/pixel-effects.json");
    let text = std::fs::read_to_string(path).expect("the corpus is where it says it is");
    let corpus: Corpus = serde_json::from_str(&text).expect("the corpus parses");
    assert!(corpus.cases.len() >= 600, "a corpus this small is not guarding anything");

    let mut wrong = Vec::new();
    let (mut bytes_seen, mut off_by_one) = (0usize, 0usize);
    for case in &corpus.cases {
        let effect = PixelEffect::parse(&case.effect);
        assert_eq!(effect.name(), case.effect, "{}: an effect this build does not know", case.name);
        let phase = phase_at(case.speed, case.now_ms);
        if (phase - case.phase).abs() > 1e-6 {
            wrong.push(format!("{}: phase {phase} against {}", case.name, case.phase));
            continue;
        }
        let params = PixelParams {
            effect,
            color: case.color,
            color2: case.color2,
            brightness: case.brightness,
            speed: case.speed,
            size: case.size,
            reverse: case.reverse,
            mirror: case.mirror,
            segments: case.segments,
        };
        let got = render(&params, phase, case.now_ms, case.count);
        let want = bytes(&case.rgb);
        assert_eq!(got.len(), want.len(), "{}", case.name);
        for (i, (g, w)) in got.iter().zip(&want).enumerate() {
            bytes_seen += 1;
            match g.abs_diff(*w) {
                0 => {}
                1 => off_by_one += 1,
                _ => {
                    wrong.push(format!("{}: byte {i} is {g}, the node draws {w}", case.name));
                    break;
                }
            }
        }
    }
    assert!(wrong.is_empty(), "{} cases disagree:\n  {}", wrong.len(), wrong.join("\n  "));
    // A rounding edge is rare; a formula that is slightly wrong everywhere is not.
    assert!(
        off_by_one * 100 <= bytes_seen,
        "{off_by_one} of {bytes_seen} bytes are one off — more than rounding explains"
    );
}
